/** 官方图片管线认的 4 种 MIME（与 ui-conversation 的 isImageMediaType 一致）。 */
const ACCEPTED_IMAGE_MIME = new Set(['image/png', 'image/jpeg', 'image/webp', 'image/gif'])

/** MIME → 扩展名。表里没有就退回按文件名取。 */
const MIME_EXT = {
  'image/png': 'png',
  'image/jpeg': 'jpg',
  'image/webp': 'webp',
  'image/gif': 'gif',
  'image/bmp': 'bmp',
  'image/tiff': 'tiff',
  'image/avif': 'avif',
  'image/heic': 'heic',
  'image/svg+xml': 'svg',
  'audio/mpeg': 'mp3',
  'audio/mp3': 'mp3',
  'audio/wav': 'wav',
  'audio/x-wav': 'wav',
  'audio/ogg': 'ogg',
  'audio/mp4': 'm4a',
  'audio/aac': 'aac',
  'audio/flac': 'flac',
  'audio/opus': 'opus',
  'video/mp4': 'mp4',
  'video/webm': 'webm',
  'video/quicktime': 'mov',
  'video/x-matroska': 'mkv',
  'application/pdf': 'pdf',
  'application/msword': 'doc',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.ms-excel': 'xls',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'application/vnd.ms-powerpoint': 'ppt',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
  'text/plain': 'txt',
  'text/markdown': 'md',
  'text/csv': 'csv',
  'application/json': 'json',
  'application/zip': 'zip',
  'application/x-zip-compressed': 'zip',
  'application/gzip': 'gz',
  'application/x-tar': 'tar',
  'application/x-7z-compressed': '7z',
  'application/x-rar-compressed': 'rar',
}

const IMAGE_EXTS = new Set(['png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp', 'tif', 'tiff', 'avif', 'heic', 'heif', 'svg'])
const AUDIO_EXTS = new Set(['mp3', 'wav', 'ogg', 'oga', 'm4a', 'aac', 'flac', 'opus', 'wma', 'aiff'])
const VIDEO_EXTS = new Set(['mp4', 'webm', 'mov', 'mkv', 'avi', 'm4v', 'wmv'])
const DOC_EXTS = new Set(['doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'odt', 'ods', 'odp', 'rtf', 'pages', 'numbers', 'key'])
const TEXT_EXTS = new Set(['txt', 'md', 'markdown', 'csv', 'tsv', 'json', 'jsonl', 'log', 'yaml', 'yml', 'xml', 'html', 'htm', 'ini', 'toml'])
const ARCHIVE_EXTS = new Set(['zip', 'gz', 'tgz', 'tar', '7z', 'rar', 'bz2', 'xz'])

/* ---------------------------------------------------------------------------
 * 1. 纯逻辑：短名规划
 * ------------------------------------------------------------------------- */

/**
 * 取扩展名：优先信 MIME，其次信文件名后缀，都没有就 bin。
 * @param mime - 浏览器给的 MIME。
 * @param fileName - 原始文件名。
 * @returns 小写扩展名（不含点）。
 */
function extensionFor(mime, fileName) {
  const byMime = typeof mime === 'string' ? MIME_EXT[mime.toLowerCase()] : undefined
  if (byMime !== undefined) return byMime
  const match = /\.([A-Za-z0-9]{1,8})$/.exec(typeof fileName === 'string' ? fileName : '')
  return match === null ? 'bin' : match[1].toLowerCase()
}

/**
 * 归类：决定用哪个前缀。MIME 优先，MIME 缺失/泛化时看扩展名。
 * @param mime - 浏览器给的 MIME。
 * @param ext - extensionFor 的结果。
 * @returns settings.prefixes 的键之一。
 */
function categoryOf(mime, ext) {
  const type = typeof mime === 'string' ? mime.toLowerCase() : ''
  if (type.startsWith('image/')) return 'image'
  if (type.startsWith('audio/')) return 'audio'
  if (type.startsWith('video/')) return 'video'
  if (IMAGE_EXTS.has(ext)) return 'image'
  if (AUDIO_EXTS.has(ext)) return 'audio'
  if (VIDEO_EXTS.has(ext)) return 'video'
  if (type === 'application/pdf' || ext === 'pdf') return 'pdf'
  if (DOC_EXTS.has(ext)) return 'document'
  if (type.startsWith('text/') || TEXT_EXTS.has(ext)) return 'text'
  if (ARCHIVE_EXTS.has(ext)) return 'archive'
  return 'other'
}

/**
 * 前缀兜底：配置缺项或值不合法时回落到 file。
 * @param config - 插件配置。
 * @param category - categoryOf 的结果。
 * @returns 可用于文件名的前缀。
 */
function prefixFor(config, category) {
  const prefixes = config !== undefined && config.prefixes !== undefined ? config.prefixes : {}
  const candidate = prefixes[category]
  const usable = typeof candidate === 'string' && /^[A-Za-z0-9][A-Za-z0-9_-]{0,23}$/.test(candidate)
  return usable ? candidate : 'file'
}

/** 计数器持久化的键与容量：只留最近用过的 N 个会话，避免 localStorage 无限膨胀。 */
const COUNTER_STORAGE_KEY = 'dsh-inline-pastes:v2:counters'
const COUNTER_SESSION_LIMIT = 100

/** 取 localStorage（拿不到或不可用就返回 undefined，功能退化为「仅本次页面会话有效」）。 */
function browserStorage() {
  try {
    const storage = globalThis.localStorage
    return storage === undefined || storage === null ? undefined : storage
  } catch (error) {
    return undefined
  }
}

/** 读持久化的计数器表；任何异常都当成空表。 */
function readCounters(storage) {
  try {
    const raw = storage?.getItem?.(COUNTER_STORAGE_KEY)
    if (typeof raw !== 'string' || raw === '') return {}
    const parsed = JSON.parse(raw)
    const sessions = parsed?.sessions
    return sessions !== null && typeof sessions === 'object' ? sessions : {}
  } catch (error) {
    return {}
  }
}

/** 写持久化的计数器表；写失败（隐私模式/配额）不影响功能。 */
function writeCounters(storage, counters) {
  try {
    storage?.setItem?.(COUNTER_STORAGE_KEY, JSON.stringify({ version: 1, sessions: counters }))
  } catch (error) {
    /* 忽略 */
  }
}

/**
 * 名字计数器。
 *
 * 规则：`<prefix>-<n>.<ext>`，n 从 config.startIndex 起，只增不减（删掉胶囊也不
 * 回收，避免同一条消息里出现重名）；万一撞上已用过的名字就继续往后找。
 *
 * 范围由 config.counterScope 决定：
 *   - `'message'`（默认）：**每条消息都从 image-1 重开**。调用方在「本条消息还没插过
 *     胶囊」时传 `{ reset: true }`（见 startsNewMessage）；同一条消息内接着粘则继续排。
 *   - `'session'`：整个会话连续排，`reset` 被忽略。
 *
 * 计数**持久化到 localStorage**（按会话分键，只留最近 100 个会话）：刷新页面后同一
 * 条未发送的消息接着往下排，不会把 image-1 又发一遍。持久化不可用时退化为仅本次页面有效。
 * @param config - 插件配置（读 startIndex / prefixes / counterScope）。
 * @param storage - 可选的 localStorage 形态对象（单测注入假实现）。
 * @returns 计数器对象。
 */
function createNameBook(config, storage) {
  const counters = new Map()
  const used = new Set()
  const startIndex = Number.isSafeInteger(config?.startIndex) ? config.startIndex : 1
  let loaded = false

  const ensureLoaded = () => {
    if (loaded) return
    loaded = true
    for (const [sessionId, entry] of Object.entries(readCounters(storage))) {
      const prefixes = entry?.prefixes
      if (prefixes === null || typeof prefixes !== 'object') continue
      counters.set(sessionId, { ...prefixes })
    }
  }

  const persist = () => {
    if (storage === undefined) return
    const sessions = {}
    for (const [sessionId, prefixes] of [...counters.entries()].slice(-COUNTER_SESSION_LIMIT)) sessions[sessionId] = { prefixes }
    writeCounters(storage, sessions)
  }

  return {
    /**
     * 规划下一个名字。
     * @param sessionId - 会话标识（计数隔离的维度）。
     * @param mime - 浏览器给的 MIME。
     * @param fileName - 原始文件名。
     * @param options.reset - 本条消息的首张图（counterScope='message' 时从 1 重开）。
     * @returns {name, category, ext, index}
     */
    next(sessionId, mime, fileName, options) {
      ensureLoaded()
      const ext = extensionFor(mime, fileName)
      const category = categoryOf(mime, ext)
      const prefix = prefixFor(config, category)
      const perMessage = config?.counterScope !== 'session'
      const reset = perMessage && options?.reset === true
      const existing = counters.get(sessionId)
      const sessionCounters = existing === undefined || reset ? {} : existing
      if (reset) {
        /* 换了新消息：把上一条消息留下的「已用名字」一起忘掉。
         * 名字跨消息重复本来就是预期的（每条消息都从 image-1 起），
         * 不清掉的话碰撞兜底会一路把新消息推到 image-4。 */
        const marker = `${sessionId}\u0000`
        for (const key of [...used]) if (key.startsWith(marker)) used.delete(key)
      }
      let index = sessionCounters[prefix]
      if (!Number.isSafeInteger(index) || index < startIndex) index = startIndex
      let name = `${prefix}-${index}.${ext}`
      while (used.has(`${sessionId}\u0000${name}`)) {
        index += 1
        name = `${prefix}-${index}.${ext}`
      }
      sessionCounters[prefix] = index + 1
      /* 重新插入以保持「最近使用在末尾」，持久化时按这个顺序截断 */
      counters.delete(sessionId)
      counters.set(sessionId, sessionCounters)
      used.add(`${sessionId}\u0000${name}`)
      persist()
      return { name, category, ext, index }
    },
    /** 清掉某个会话的计数（内存 + 持久化）。 */
    forget(sessionId) {
      ensureLoaded()
      counters.delete(sessionId)
      const marker = `${sessionId}\u0000`
      for (const key of [...used]) if (key.startsWith(marker)) used.delete(key)
      persist()
    },
  }
}

/* ---------------------------------------------------------------------------
 * 2. 纯逻辑：在文本里找出「悬浮光标落在哪个名字上」
 * ------------------------------------------------------------------------- */

/** 名字允许的字符（image-1.png 全在其中）。 */
const TOKEN_CHAR = /[A-Za-z0-9._-]/

/**
 * 名字的机器可读形态 `<prefix>-<n>.<ext>`。
 * 捕获组 1 是序号，用来「到同一条消息的原生图片里按序号取图」——
 * 名字按消息重开之后，只有同消息内定位才不会串到别的消息上去。
 */
const NAME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,23}-(\d+)\.[A-Za-z0-9]{1,8}$/

/** 悬浮候选表：本插件登记过的名字，或者长得像本插件命名规则的名字。 */
function candidateTable(registry) {
  return { has: (name) => registry.has(name) || NAME_PATTERN.test(name) }
}

/**
 * 从 (text, offset) 展开出所在 token。
 * @param text - 文本节点内容。
 * @param offset - 光标在该文本节点里的偏移。
 * @returns {token,start,end} 或 null。
 */
function tokenAt(text, offset) {
  if (typeof text !== 'string' || text.length === 0) return null
  let index = Math.min(Math.max(offset, 0), text.length - 1)
  if (!TOKEN_CHAR.test(text[index]) && index > 0 && TOKEN_CHAR.test(text[index - 1])) index -= 1
  if (!TOKEN_CHAR.test(text[index])) return null
  let start = index
  let end = index + 1
  while (start > 0 && TOKEN_CHAR.test(text[start - 1])) start -= 1
  while (end < text.length && TOKEN_CHAR.test(text[end])) end += 1
  return { token: text.slice(start, end), start, end }
}

/** 名字 token 的扫描窗口（两侧各取这么多字符，够覆盖「紧贴中文/数字」的写法）。 */
const LOOKUP_WINDOW = 48

/**
 * 在 (text, offset) 处查找一个「已记住的名字」。
 *
 * 两个坑：
 *   1. 允许的字符集含 `.`，句末句点会被吞进 token（`见 image-1.png.`）→ 尾部逐字回退；
 *   2. 名字紧跟在字母数字后面时左边也会被吞（`功能1image-1.png`）→ 慢路径在小窗口里
 *      枚举所有子串。
 * @param table - 有 has(name) 的名字表。
 * @param text - 文本节点内容。
 * @param offset - 光标偏移。
 * @returns {token,start,end} 或 null。
 */
function lookupName(table, text, offset) {
  if (typeof text !== 'string' || text.length === 0) return null
  const base = tokenAt(text, offset)
  if (base !== null) {
    let token = base.token
    let end = base.end
    while (token.length > 0) {
      if (table.has(token)) return { token, start: base.start, end }
      token = token.slice(0, -1)
      end -= 1
    }
  }

  const from = Math.max(0, offset - LOOKUP_WINDOW)
  const to = Math.min(text.length, offset + LOOKUP_WINDOW)
  const window = text.slice(from, to)
  const scanner = /[A-Za-z0-9][A-Za-z0-9._-]*/g
  let match = scanner.exec(window)
  while (match !== null) {
    const matchStart = from + match.index
    const matchEnd = matchStart + match[0].length
    if (offset >= matchStart && offset <= matchEnd) {
      for (let start = matchStart; start < matchEnd; start += 1) {
        let candidate = text.slice(start, matchEnd)
        let end = matchEnd
        while (candidate.length > 0) {
          if (table.has(candidate)) return { token: candidate, start, end }
          candidate = candidate.slice(0, -1)
          end -= 1
        }
      }
    }
    match = scanner.exec(window)
  }
  return null
}

/* ---------------------------------------------------------------------------
 * 3. 小工具
 * ------------------------------------------------------------------------- */

/**
 * 读服务：优先 ctx.get，退化到同名属性（不同 DSH 版本的 ctx 形态有差异）。
 * @param ctx - 客户端上下文。
 * @param name - 服务名。
 * @returns 服务实例或 undefined。
 */
function service(ctx, name) {
  if (ctx === undefined || ctx === null) return undefined
  try {
    if (typeof ctx.get === 'function') {
      const found = ctx.get(name)
      if (found !== undefined && found !== null) return found
    }
  } catch (error) {
    /* 未注入的服务在某些版本会抛，继续走属性兜底 */
  }
  const direct = ctx[name]
  return direct === undefined ? undefined : direct
}

/** 体积格式化。 */
function formatBytes(bytes) {
  if (!Number.isFinite(bytes) || bytes <= 0) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(bytes < 10240 ? 1 : 0)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

/** 尺寸 + 体积的说明行。 */
function describe(record) {
  const parts = []
  if (Number.isFinite(record.width) && Number.isFinite(record.height)) parts.push(`${record.width}×${record.height}`)
  const size = formatBytes(record.bytes)
  if (size !== '') parts.push(size)
  return parts.join(' · ')
}

/** element.closest 的安全版。 */
function closest(element, selector) {
  if (element === undefined || element === null || typeof element.closest !== 'function') return null
  return element.closest(selector)
}

/** 用新名字重建 File（官方 createDrafts / encodeImage 都读 file.name）。 */
function renameFile(file, name) {
  try {
    return new File([file], name, { type: file.type, lastModified: file.lastModified })
  } catch (error) {
    /* 极端环境没有 File 构造器：在 Blob 上挂个 name 顶上（读取方只认 .name/.type/.size） */
    try {
      const blob = file.slice(0, file.size, file.type)
      Object.defineProperty(blob, 'name', { value: name, configurable: true })
      return blob
    } catch (inner) {
      return file
    }
  }
}

/** 从剪贴板里取图片文件；混进任何非图片文件就整批放弃（交还官方）。 */
function imagesFrom(data) {
  const files = []
  if (data === undefined || data === null) return files
  const items = data.items
  if (items === undefined || items === null || typeof items.length !== 'number') return files
  for (let index = 0; index < items.length; index += 1) {
    const item = items[index]
    if (item === undefined || item === null || item.kind !== 'file') continue
    const file = typeof item.getAsFile === 'function' ? item.getAsFile() : null
    if (file === null || file === undefined) continue
    if (!ACCEPTED_IMAGE_MIME.has(file.type)) return []
    files.push(file)
  }
  return files
}

/**
 * 事件目标是不是输入框（先认官方标记，找不到标记才退回 contenteditable）。
 * 这样即使将来官方改了属性名，也不会退化成「全页面任何 contenteditable 都接管」。
 * @param doc - document。
 * @param target - 事件目标。
 * @returns 是否在输入框内。
 */
function isComposerTarget(doc, target) {
  let marker = null
  try {
    marker = doc.querySelector('[data-input-scroll]')
  } catch (error) {
    marker = null
  }
  if (marker !== null) return closest(target, '[data-input-scroll]') !== null
  return closest(target, '[contenteditable="true"]') !== null
}

/* ---------------------------------------------------------------------------
 * 4. 名字登记表（名字 → 预览用 object URL + 元数据）
 * ------------------------------------------------------------------------- */

/**
 * 记住「这个名字对应哪张图」。
 *
 * object URL 由本插件自己创建、自己回收——不复用草稿附件的 previewUrl，因为
 * 官方在发送落定后会把它 revoke 掉（settleSubmittedAttachments）。
 * @param config - 插件配置（maxRemembered）。
 * @param onGrow - 记录补齐尺寸后的回调（用来刷新已打开的预览卡）。
 * @returns 登记表。
 */
function createRegistry(config, onGrow) {
  const records = new Map()
  /**
   * 短名别名 → 完整文件名。
   *
   * 胶囊显示短名（`pic-1`）时，悬浮落在胶囊上读到的是短名，而登记表按完整文件名
   * （`pic-1.png`，也就是模型侧看到的名字）存。这里建一张别名索引，两种写法都查得到同一张图。
   */
  const aliases = new Map()
  const limit = Number.isSafeInteger(config?.maxRemembered) && config.maxRemembered > 0 ? config.maxRemembered : 600
  const revoke = (url) => {
    try {
      URL.revokeObjectURL(url)
    } catch (error) {
      /* 释放失败不影响功能 */
    }
  }
  /** 丢掉指向该完整文件名的别名（同名覆盖与淘汰时都要清，避免别名指到已释放的图）。 */
  const dropAliasesFor = (name) => {
    for (const [alias, target] of [...aliases]) if (target === name) aliases.delete(alias)
  }
  return {
    size: () => records.size,
    has: (name) => records.has(name) || aliases.has(name),
    /** 取记录：完整文件名与短名别名都认。 */
    get(name) {
      const direct = records.get(name)
      if (direct !== undefined) return direct
      const real = aliases.get(name)
      return real === undefined ? undefined : records.get(real)
    },
    /**
     * 登记一条记录（同名覆盖）。
     * @param entry - { name, sessionId, file, mediaType, bytes }。
     * @returns 登记后的记录。
     */
    remember(entry) {
      const previous = records.get(entry.name)
      if (previous !== undefined) {
        records.delete(entry.name)
        revoke(previous.url)
      }
      dropAliasesFor(entry.name)
      const record = {
        name: entry.name,
        sessionId: entry.sessionId,
        mediaType: entry.mediaType,
        bytes: Number.isFinite(entry.bytes) ? entry.bytes : undefined,
        url: URL.createObjectURL(entry.file),
        width: undefined,
        height: undefined,
      }
      records.set(entry.name, record)
      const alias = displayNameFor(entry.name, config)
      if (alias !== '' && alias !== entry.name) aliases.set(alias, entry.name)
      probeDimensions(record, entry.file, onGrow)
      while (records.size > limit) {
        const oldest = records.keys().next()
        if (oldest.done === true) break
        const victim = records.get(oldest.value)
        records.delete(oldest.value)
        if (victim !== undefined) {
          revoke(victim.url)
          dropAliasesFor(victim.name)
        }
      }
      return record
    },
    dispose() {
      for (const record of records.values()) revoke(record.url)
      records.clear()
      aliases.clear()
    },
  }
}

/** 只读图片头拿尺寸（失败就算了；探测用的 object URL 读完立刻释放）。 */
function probeDimensions(record, file, onGrow) {
  if (typeof Image !== 'function') return
  const probe = new Image()
  const release = () => {
    try {
      URL.revokeObjectURL(probe.src)
    } catch (error) {
      /* 忽略 */
    }
  }
  probe.onload = () => {
    record.width = probe.naturalWidth
    record.height = probe.naturalHeight
    if (typeof onGrow === 'function') onGrow(record)
    release()
  }
  probe.onerror = release
  probe.src = URL.createObjectURL(file)
}

/* ---------------------------------------------------------------------------
 * 5. 预览卡（纯 DOM，fixed 定位，pointer-events:none）
 * ------------------------------------------------------------------------- */

/** 注入样式（幂等）。 */
function installStyles(doc, css) {
  if (typeof css !== 'string' || css.trim() === '') return null
  const existing = doc.querySelector('style[data-dsh-inline-pastes]')
  if (existing !== null) return existing
  const style = doc.createElement('style')
  style.setAttribute('data-dsh-inline-pastes', '')
  style.textContent = css
  const host = doc.head ?? doc.documentElement
  if (host !== null && host !== undefined) host.appendChild(style)
  return style
}

/**
 * 建预览卡。
 * @param doc - document。
 * @param config - 插件配置。
 * @returns {show, hide, isOpen, refresh, dispose}。
 */
function createPreviewCard(doc, config) {
  const root = doc.createElement('div')
  root.className = 'dsh-ip-card'
  root.setAttribute('role', 'tooltip')
  root.setAttribute('aria-hidden', 'true')
  const image = doc.createElement('img')
  image.className = 'dsh-ip-img'
  image.alt = ''
  image.decoding = 'async'
  const meta = doc.createElement('div')
  meta.className = 'dsh-ip-meta'
  const nameEl = doc.createElement('span')
  nameEl.className = 'dsh-ip-name'
  const subEl = doc.createElement('span')
  subEl.className = 'dsh-ip-sub'
  meta.append(nameEl, subEl)
  root.append(image, meta)
  const host = doc.body ?? doc.documentElement
  if (host !== null && host !== undefined) host.appendChild(root)

  let current = null

  const place = (rect) => {
    const win = doc.defaultView
    const viewWidth = win?.innerWidth ?? 1024
    const viewHeight = win?.innerHeight ?? 768
    const box = root.getBoundingClientRect()
    const margin = 8
    let left = rect.left + rect.width / 2 - box.width / 2
    left = Math.max(margin, Math.min(left, viewWidth - box.width - margin))
    let top = rect.top - box.height - margin
    if (top < margin) top = rect.bottom + margin
    if (top + box.height > viewHeight - margin) top = Math.max(margin, viewHeight - box.height - margin)
    root.style.left = `${Math.round(left)}px`
    root.style.top = `${Math.round(top)}px`
  }

  return {
    isOpen: () => root.dataset.open === 'true',
    /**
     * 打开（或原地刷新）预览卡。
     * @param record - 名字记录。
     * @param rect - 锚点矩形。
     */
    show(record, rect) {
      current = record
      image.src = record.url
      nameEl.textContent = record.name
      subEl.textContent = config?.showMeta === false ? '' : describe(record)
      root.dataset.open = 'true'
      root.setAttribute('aria-hidden', 'false')
      place(rect)
    },
    /** 记录补齐尺寸后原地刷新文案。 */
    refresh(record) {
      if (current === null || current.name !== record.name) return
      if (config?.showMeta === false) return
      subEl.textContent = describe(record)
    },
    hide() {
      if (root.dataset.open !== 'true') return
      root.dataset.open = 'false'
      root.setAttribute('aria-hidden', 'true')
      current = null
    },
    dispose() {
      root.remove()
    },
  }
}

/* ---------------------------------------------------------------------------
 * 6. 光标位置 → 名字
 * ------------------------------------------------------------------------- */

/** 取坐标处的文本位置（caretPositionFromPoint / caretRangeFromPoint 双兼容）。 */
function caretFromPoint(doc, x, y) {
  if (typeof doc.caretPositionFromPoint === 'function') {
    const position = doc.caretPositionFromPoint(x, y)
    if (position !== null && position !== undefined && position.offsetNode !== undefined) {
      return { node: position.offsetNode, offset: position.offset }
    }
  }
  if (typeof doc.caretRangeFromPoint === 'function') {
    const range = doc.caretRangeFromPoint(x, y)
    if (range !== null && range !== undefined) return { node: range.startContainer, offset: range.startOffset }
  }
  return null
}

/** 取一段文字的矩形（用于把预览卡对准这个名字）。 */
function rectOfRange(doc, node, start, end) {
  try {
    const range = doc.createRange()
    range.setStart(node, start)
    range.setEnd(node, end)
    const rect = range.getBoundingClientRect()
    return rect.width === 0 && rect.height === 0 ? null : rect
  } catch (error) {
    return null
  }
}

/** 是否位于会话表面（输入框 / 会话滚动区）。找不到标记时放行，避免将来改属性直接失效。 */
function inConversationSurface(doc, element) {
  const selector = '[data-input-scroll],[data-conversation-scroll]'
  let anyMarker = null
  try {
    anyMarker = doc.querySelector(selector)
  } catch (error) {
    anyMarker = null
  }
  if (anyMarker === null) return true
  return closest(element, selector) !== null
}

/**
 * 悬浮命中判定：先看官方胶囊，再看普通文字里的名字。
 * @param doc - document。
 * @param registry - 名字登记表。
 * @param x - 指针 x。
 * @param y - 指针 y。
 * @returns {key, record, rect} 或 null。
 */
function hitTest(doc, registry, x, y) {
  const element = typeof doc.elementFromPoint === 'function' ? doc.elementFromPoint(x, y) : null
  if (element === null || element === undefined) return null

  const chip = closest(element, '[data-composer-chip]')
  if (chip !== null) {
    if (registry.size() === 0) return null
    const label = (chip.textContent ?? '').trim()
    if (label === '' || !registry.has(label)) return null
    return { key: `chip:${label}`, record: registry.get(label), rect: chip.getBoundingClientRect() }
  }

  if (!inConversationSurface(doc, element)) return null
  const point = caretFromPoint(doc, x, y)
  if (point === null || point.node === null || point.node === undefined || point.node.nodeType !== 3) return null
  const found = lookupName(candidateTable(registry), point.node.data, point.offset)
  if (found === null) return null
  const rect = rectOfRange(doc, point.node, found.start, found.end)
  if (rect === null) return null

  /* ① 先到**同一条消息的原生图片**里按序号取图：
   *    名字按消息重开，只有同消息内定位才准；顺带让刷新页面后的历史消息也能预览
   *    （用的是会话授权的持久图片地址，不依赖本插件的内存登记表）。 */
  const inline = messageImage(element, found.token)
  if (inline !== null) {
    return { key: `msg:${found.token}:${inline.src}`, record: { name: found.token, url: inline.src, width: inline.width, height: inline.height }, rect }
  }

  /* ② 退回本插件自己的登记表（输入框草稿里的名字、以及刚粘完还没发送的场景）。 */
  const record = registry.get(found.token)
  if (record === undefined) return null
  return { key: `text:${found.token}:${found.start}`, record, rect }
}

/**
 * 在「悬浮元素所在的那条消息」里按序号取出原生图片。
 * @param element - 悬浮命中的元素。
 * @param name - image-3.png 这类名字。
 * @returns {src,width,height} 或 null。
 */
function messageImage(element, name) {
  const match = NAME_PATTERN.exec(name)
  if (match === null) return null
  const index = Number(match[1])
  if (!Number.isSafeInteger(index) || index < 1) return null
  const chatItem = closest(element, '[data-chat-node-key]')
  const scope = chatItem === null ? firstAncestorWithAttachments(element) : chatItem
  if (scope === null || typeof scope.querySelectorAll !== 'function') return null
  const images = scope.querySelectorAll('[data-message-attachments] img')
  const image = images[index - 1]
  if (image === undefined || image === null) return null
  const src = typeof image.getAttribute === 'function' ? image.getAttribute('src') : image.src
  if (typeof src !== 'string' || src === '') return null
  return { src, width: image.naturalWidth, height: image.naturalHeight }
}

/** 没有 [data-chat-node-key] 时（别的目标/老版本）退化为向上找第一个含附件行的祖先。 */
function firstAncestorWithAttachments(element) {
  let node = element
  for (let depth = 0; node !== null && node !== undefined && depth < 8; depth += 1) {
    if (typeof node.querySelector === 'function' && node.querySelector('[data-message-attachments]') !== null) return node
    node = node.parentElement
  }
  return null
}

/* ---------------------------------------------------------------------------
 * 7. 会话解析与会话图片限额
 * ------------------------------------------------------------------------- */

/**
 * 解析当前会话与它的输入门面。
 * @param ctx - 客户端上下文。
 * @returns {sessionId, shell, conversation, scopeCtx} 或 undefined。
 */
function resolveSession(ctx) {
  const conversation = service(ctx, 'conversation')
  if (conversation === undefined || conversation.input === undefined || typeof conversation.input.for !== 'function') return undefined
  const sessions = service(ctx, 'sessions')

  const uiSession = service(ctx, 'uiSession')
  const binding = typeof uiSession?.current?.getSnapshot === 'function' ? uiSession.current.getSnapshot() : undefined
  let sessionId = typeof binding?.key === 'string' && binding.key !== '' ? binding.key : undefined
  let scopeCtx = binding?.ctx

  if (sessionId === undefined && sessions !== undefined) {
    const list = typeof sessions.list?.getSnapshot === 'function' ? sessions.list.getSnapshot() : undefined
    if (list !== undefined && list !== null) {
      if (typeof list.current === 'string' && list.current !== '') sessionId = list.current
      else {
        const byId = list.byId ?? {}
        const ids = Array.isArray(list.ids) ? list.ids : Object.keys(byId)
        /* 只在能明确指认「主视图正在显示哪个会话」时才兜底。
         * 绝不 `?? ids[0]` 猜一个：猜错会把胶囊插进另一个会话的编辑器里，
         * 当前会话什么都没看到，而那边的计数器又被悄悄推进——正是这种
         * 「新会话里序号没重开」的诡异症状的来源。认不出就不接管，交还官方。 */
        sessionId = ids.find((id) => (byId[id]?.retainedBy?.mainView ?? 0) > 0)
      }
    }
  }
  if (typeof sessionId !== 'string' || sessionId === '') return undefined

  if (scopeCtx === undefined && typeof sessions?.scope === 'function') scopeCtx = sessions.scope(sessionId)
  if (scopeCtx === undefined) return undefined

  let shell
  try {
    shell = conversation.input.for(scopeCtx)
  } catch (error) {
    return undefined
  }
  if (shell === undefined || shell === null) return undefined
  return { sessionId, shell, conversation, scopeCtx }
}

/** 读会话的 imageLimits 投影（读不到就返回 undefined，跳过检查）。 */
function imageLimitsOf(ctx, sessionId) {
  try {
    const binding = service(ctx, 'sessions')?.binding?.(sessionId)
    const face = binding?.session?.projections?.faceOf?.('imageLimits')
    return typeof face?.getSnapshot === 'function' ? face.getSnapshot() : undefined
  } catch (error) {
    return undefined
  }
}

/**
 * 会不会超出会话的图片限额？超了就不接管，让官方走自己的报错提示。
 * @param limits - imageLimits 投影。
 * @param existing - 当前草稿里已有的附件描述符。
 * @param files - 本次粘贴的图片文件。
 * @returns 超限返回 true。
 */
function exceedsImageLimits(limits, existing, files) {
  if (limits === undefined || limits === null) return false
  const mediaTypes = Array.isArray(limits.mediaTypes) ? limits.mediaTypes : []
  if (mediaTypes.length > 0 && files.some((file) => !mediaTypes.includes(file.type))) return true
  const images = Array.isArray(existing) ? existing.filter((attachment) => attachment?.kind === 'image') : []
  if (Number.isFinite(limits.maxImagesPerMessage) && images.length + files.length > limits.maxImagesPerMessage) return true
  if (Number.isFinite(limits.maxImageBytes) && files.some((file) => file.size > limits.maxImageBytes)) return true
  if (Number.isFinite(limits.maxMessageImageBytes)) {
    const used = images.reduce((sum, attachment) => sum + (attachment?.file?.size ?? 0), 0)
    const added = files.reduce((sum, file) => sum + (file.size ?? 0), 0)
    if (used + added > limits.maxMessageImageBytes) return true
  }
  return false
}

/* ---------------------------------------------------------------------------
 * 7.5 发送前自检：文字里的名字 ↔ 本条消息的图片
 * ------------------------------------------------------------------------- */

/** 自检提示的前缀（既给用户看，也用来判断"这条 notice 是不是我们发的"）。 */
const AUDIT_NOTICE_PREFIX = '图片名自检：'

/**
 * 自检：草稿文字里出现的每个图片名字，都要能在本条消息的附件里一一对上，且不重复。
 *
 * 为什么只查这两个：官方给模型发图时会在每张图前面贴一行
 * `Image "image-1.png" (...)`（见 README），所以**名字是长在图上**的 ——
 * 只要名字不重复、且文字里提到的名字都真有那张图，模型就不会串。
 * 「有图但文字没点名」不算错（图照样带着名字发出去），所以不报。
 * @param chipLabels - 草稿里本插件胶囊的名字，按出现顺序。
 * @param attachmentNames - 本条草稿附件的文件名，按附件顺序。
 * @returns {ok, duplicates, dangling, message}
 */
function auditDraft(chipLabels, attachmentNames) {
  const pool = Array.isArray(attachmentNames) ? attachmentNames : []
  const seen = new Set()
  const duplicates = []
  const dangling = []
  for (const label of Array.isArray(chipLabels) ? chipLabels : []) {
    if (label === '') continue
    if (seen.has(label)) {
      if (!duplicates.includes(label)) duplicates.push(label)
    } else {
      seen.add(label)
    }
    if (!pool.includes(label) && !dangling.includes(label)) dangling.push(label)
  }
  const problems = []
  if (duplicates.length > 0) problems.push(`文字里重复出现 ${duplicates.join('、')}`)
  if (dangling.length > 0) problems.push(`${dangling.join('、')} 在本条消息里找不到对应图片`)
  return {
    ok: problems.length === 0,
    duplicates,
    dangling,
    message: problems.length === 0 ? undefined : problems.join('；'),
  }
}

/**
 * 从 shell 快照 + conversation 服务里取出自检需要的两个序列。
 *
 * 名字取的是**完整文件名**：优先从胶囊的隐藏 ref 还原（`dsh-inline-paste:pic-1.png`），
 * 拿不到 ref 才退回 label。这一步很关键——胶囊显示的是短名 `pic-1`（见 chipDisplay），
 * 而附件名是 `pic-1.png`，若拿显示名去比对，自检会把每张图都误报成「找不到对应图片」。
 */
function auditInputs(state, conversation) {
  const occurrences = Array.isArray(state?.occurrences) ? state.occurrences : []
  const chipLabels = occurrences
    .filter((item) => item?.source === SOURCE)
    .map((item) => (typeof item?.ref === 'string' && item.ref !== '' ? nameFromRef(item.ref) : item?.label ?? ''))
  const ids = Array.isArray(state?.attachmentIds) ? state.attachmentIds : []
  let attachmentNames = []
  try {
    const descriptors = typeof conversation?.resolveDraftAttachments === 'function' ? conversation.resolveDraftAttachments(ids) : []
    attachmentNames = (Array.isArray(descriptors) ? descriptors : [])
      .map((descriptor) => descriptor?.file?.name ?? '')
      .filter((name) => typeof name === 'string' && name !== '')
  } catch (error) {
    attachmentNames = []
  }
  return { chipLabels, attachmentNames }
}

/**
 * 自检器：跟着当前会话的输入状态跑，必要时在输入框上方挂一条提示。
 *
 * 提示走官方的 composer notice（`shell.notify('info', …)`，渲染成输入框上方那条
 * `.notice` 小条），不自己往 React 管的 DOM 里塞节点；拿不到就退回 console。
 * 清提示时只清「内容还是我们写的那条」，绝不动官方自己发的通知（错误通知是 toast）。
 * @param ctx - 客户端上下文。
 * @param deps - 依赖包。
 * @returns {evaluate, overrideRev, dispose}
 */
function createAuditor(ctx, deps) {
  let shell = null
  let offState = null
  let ourNotice = null
  let overrideRev

  const clearNotice = () => {
    if (ourNotice === null) return
    const text = ourNotice
    ourNotice = null
    try {
      const current = shell?.notices?.getSnapshot?.()
      if (current !== null && current !== undefined && current.text !== text) return
      shell?.notices?.set?.(null)
    } catch (error) {
      /* 清不掉就算了，下次内容变化会覆盖 */
    }
  }

  const showNotice = (text) => {
    if (ourNotice === text) return
    ourNotice = text
    try {
      if (typeof shell?.notify === 'function') {
        shell.notify('info', text)
        return
      }
    } catch (error) {
      /* 退回 console */
    }
    deps.report(text, undefined)
  }

  /** 重算一次；返回 {verdict, draftRev} 或 null（当前没有可自检的会话）。 */
  const evaluate = () => {
    if (settings.auditBeforeSend !== true || settings.enabled !== true) {
      /* 自检被关掉时，把自己之前挂的那条提示一起撤掉，别留个孤儿条 */
      clearNotice()
      return null
    }
    const session = resolveSession(ctx)
    if (session === undefined) {
      shell = null
      clearNotice()
      return null
    }
    if (session.shell !== shell) {
      try {
        offState?.()
      } catch (error) {
        /* 忽略 */
      }
      shell = session.shell
      offState = typeof shell.state?.subscribe === 'function' ? shell.state.subscribe(() => evaluate()) : null
    }
    const state = shell.state?.getSnapshot?.()
    const { chipLabels, attachmentNames } = auditInputs(state, session.conversation)
    const verdict = auditDraft(chipLabels, attachmentNames)
    if (deps.debug !== undefined) {
      deps.debug.audit = { at: Date.now(), ...verdict, chipLabels, attachmentNames, draftRev: state?.draftRev }
    }
    if (verdict.ok === true) clearNotice()
    else showNotice(`${AUDIT_NOTICE_PREFIX}${verdict.message}（再按一次回车仍可发送）`)
    return { verdict, draftRev: state?.draftRev, shell }
  }

  return {
    evaluate,
    /** 该草稿版本是否已经警告过（警告过就放行，避免把用户卡死）。 */
    isOverridden: (rev) => overrideRev !== undefined && overrideRev === rev,
    markOverridden: (rev) => {
      overrideRev = rev
    },
    dispose: () => {
      try {
        offState?.()
      } catch (error) {
        /* 忽略 */
      }
      offState = null
      clearNotice()
    },
  }
}

/**
 * 装发送前拦截：镜像官方 composer 的回车判定（Shift+Enter 换行、输入法组合中、
 * Alt/AltGraph 都放行），只在自检不通过时拦**第一次**回车。
 * @param deps - 依赖包（含 auditor / doc）。
 * @returns 卸载函数。
 */
function installSendGuard(deps) {
  const doc = deps.doc
  const auditor = deps.auditor
  const onKeyDown = (event) => {
    if (settings.auditBeforeSend !== true || settings.blockOnAuditFailure !== true || settings.enabled !== true) return
    if (event.key !== 'Enter' || event.isComposing === true || event.keyCode === 229) return
    if (event.shiftKey === true || event.altKey === true) return
    if (typeof event.getModifierState === 'function' && event.getModifierState('AltGraph')) return
    if (!isComposerTarget(doc, event.target)) return

    const result = auditor.evaluate()
    if (result === null || result.verdict.ok === true) return
    if (auditor.isOverridden(result.draftRev)) return
    auditor.markOverridden(result.draftRev)
    if (typeof event.preventDefault === 'function') event.preventDefault()
    if (typeof event.stopImmediatePropagation === 'function') event.stopImmediatePropagation()
  }
  doc.addEventListener('keydown', onKeyDown, true)
  return () => doc.removeEventListener('keydown', onKeyDown, true)
}

/* ---------------------------------------------------------------------------
 * 8. 粘贴接管
 * ------------------------------------------------------------------------- */

/**
 * 这次粘贴是不是「本条消息的第一张图」——也就是要不要从 image-1 重开。
 *
 * 判据是**本条消息里还没有本插件的任何痕迹**：
 *   ① 草稿里没有本插件的胶囊（occurrences 里没有 source === SOURCE 的项），并且
 *   ② 草稿附件里没有本插件挂上去的那几个（mine 集合里还留着的 id）。
 *
 * 为什么要看 ②：用户完全可能把胶囊从文字里删掉、却把 dock 里的缩略图留着。只看 ① 的话
 * 下一次粘贴会从 image-1 重开，而同一条消息里已经有一个 image-1 的附件了 —— 一条消息
 * 出现两个 image-1，模型侧就真的分不清哪张是哪张。
 *
 * 只看「草稿空不空」也不行：像「1、功能1 [图]」这种先打字再插图的写法，草稿是非空的，
 * 但它确实是本条消息的第一张图。
 * @param state - shell 的输入快照。
 * @param mine - 本插件挂上去、且可能还在草稿里的附件 id 集合。
 * @returns 是否从 1 重开。
 */
function startsNewMessage(state, mine) {
  const ids = Array.isArray(state?.attachmentIds) ? state.attachmentIds : []
  if (mine !== undefined && mine.size > 0) {
    /* 已经不在草稿里的 id（发送完/被删掉）顺手收缩，集合不会无限长大 */
    for (const id of [...mine]) if (!ids.includes(id)) mine.delete(id)
    if (ids.some((id) => mine.has(id))) return false
  }
  const occurrences = state?.occurrences
  if (Array.isArray(occurrences)) return occurrences.every((item) => item?.source !== SOURCE)
  /* 快照里没有 occurrences（版本差异）时退化为「草稿与附件都空」 */
  const draft = typeof state?.draft === 'string' ? state.draft.trim() : ''
  return draft === '' && ids.length === 0
}

/**
 * 记一次粘贴现场（调试钩子用；没有钩子时静默跳过）。
 * @param deps - 依赖包。
 * @param payload - 现场数据。
 */
function notePaste(deps, payload) {
  if (deps === undefined || deps.debug === undefined || deps.debug === null) return
  deps.debug.lastPaste = payload
}

/**
 * 处理一次粘贴；返回 true 表示「这次粘贴我全权处理了」。
 * @param ctx - 客户端上下文。
 * @param deps - { doc, nameBook, registry, report }。
 * @param event - paste 事件。
 * @returns 是否已接管。
 */
function handlePaste(ctx, deps, event) {
  if (settings.interceptPaste !== true || settings.enabled !== true) return false
  const doc = deps.doc
  const data = event.clipboardData
  if (data === undefined || data === null) return false
  if (!isComposerTarget(doc, event.target)) return false

  const files = imagesFrom(data)
  if (files.length === 0) return false

  const session = resolveSession(ctx)
  if (session === undefined) return false
  const { sessionId, shell, conversation } = session

  const state = typeof shell.state?.getSnapshot === 'function' ? shell.state.getSnapshot() : undefined
  const phase = state?.phase
  if (phase !== 'plain' && phase !== 'claimed') return false
  if (typeof shell.actions?.captureInsertion !== 'function') return false
  if (typeof shell.actions?.addAttachments !== 'function') return false
  if (typeof shell.insertReference !== 'function') return false
  if (typeof conversation.createDrafts !== 'function') return false

  const existing = typeof conversation.resolveDraftAttachments === 'function' ? conversation.resolveDraftAttachments(state?.attachmentIds ?? []) : []
  if (exceedsImageLimits(imageLimitsOf(ctx, sessionId), existing, files)) return false

  /* 1) 规划短名并重命名 File（改名要在建草稿之前，附件与胶囊才同名） */
  const reset = startsNewMessage(state, deps.mine)
  const planned = []
  for (let index = 0; index < files.length; index += 1) {
    const file = files[index]
    /* 一次粘多张时只有第一张算「本条消息的第一张」 */
    const plan = deps.nameBook.next(sessionId, file.type, file.name, { reset: reset && index === 0 })
    planned.push({ name: plan.name, file: renameFile(file, plan.name) })
  }

  /* 2) 建草稿附件（图片随 prompt 一起发，无需后台上传） */
  let drafts
  try {
    drafts = conversation.createDrafts(sessionId, planned.map((item) => item.file))
  } catch (error) {
    deps.report('createDrafts failed', error)
    return false
  }
  if (!Array.isArray(drafts) || drafts.length !== planned.length) {
    if (Array.isArray(drafts) && typeof conversation.releaseDraftAttachments === 'function') conversation.releaseDraftAttachments(drafts)
    return false
  }

  /* 3) 在光标处逐个插胶囊（每次重新取光标：插完光标会落在胶囊之后） */
  const inserted = []
  for (let index = 0; index < planned.length; index += 1) {
    let ok = false
    try {
      const span = shell.actions.captureInsertion()
      if (deps.useChips === true) {
        /* label 只决定胶囊**显示**什么（chipDisplay='short' 时是 pic-1）；
         * ref / codec / clipboardText 一路都是完整文件名 pic-1.png —— 发送时官方按
         * codec.serialize(ref) 重新序列化，所以发出去的文本与附件名始终对得上（见 README）。 */
        ok =
          shell.insertReference(
            {
              source: SOURCE,
              ref: `${REF_PREFIX}${planned[index].name}`,
              label: displayNameFor(planned[index].name, settings),
              appearance: 'file',
              clipboardText: planned[index].name,
            },
            span,
          ) === true
      } else {
        /* 拿不到 inputTriggers（注册不了 codec）时退回纯文本：
         * 插胶囊会在**发送时**报 "no serializer for reference source"，宁可少个胶囊也不能让发送失败。
         * 注意这里必须插**完整文件名**：纯文本没有 codec 兜底，插短名就会和附件名对不上。 */
        ok = typeof shell.actions.insertText === 'function' && shell.actions.insertText(planned[index].name, span) === true
      }
    } catch (error) {
      deps.report('insert reference failed', error)
      ok = false
    }
    if (!ok) break
    inserted.push(index)
  }

  if (inserted.length === 0) {
    /* 一个都没插进去：把草稿还回去，完全不拦这次粘贴 */
    notePaste(deps, { at: Date.now(), sessionId, phase, names: [], files: files.length, inserted: 0 })
    try {
      conversation.releaseDraftAttachments(drafts)
    } catch (error) {
      deps.report('releaseDraftAttachments failed', error)
    }
    return false
  }

  /* 4) 插进去的挂到草稿附件里；没插进去的释放掉 */
  const accepted = inserted.map((index) => drafts[index])
  const rejected = drafts.filter((draft, index) => !inserted.includes(index))
  try {
    shell.actions.addAttachments(accepted.map((draft) => draft.id))
    if (deps.mine !== undefined) for (const draft of accepted) deps.mine.add(draft.id)
  } catch (error) {
    deps.report('addAttachments failed', error)
  }
  if (rejected.length > 0 && typeof conversation.releaseDraftAttachments === 'function') {
    try {
      conversation.releaseDraftAttachments(rejected)
    } catch (error) {
      deps.report('releaseDraftAttachments failed', error)
    }
  }

  /* 5) 登记名字 → 预览图 */
  for (const index of inserted) {
    try {
      deps.registry.remember({
        name: planned[index].name,
        sessionId,
        file: planned[index].file,
        mediaType: planned[index].file.type,
        bytes: planned[index].file.size,
      })
    } catch (error) {
      deps.report('remember failed', error)
    }
  }

  /* 6) 剪贴板里同时有文字时，按官方顺序（先文件后文字）补上文字 */
  const text = typeof data.getData === 'function' ? data.getData('text/plain') : ''
  if (typeof text === 'string' && text !== '' && typeof shell.paste === 'function') {
    try {
      shell.paste(text)
    } catch (error) {
      deps.report('paste text failed', error)
    }
  }

  /* 给调试钩子留一份「刚才这次粘贴」的现场（控制台 __dshInlinePastes.debug 可读） */
  notePaste(deps, {
    at: Date.now(),
    sessionId,
    phase,
    files: files.length,
    inserted: inserted.length,
    names: inserted.map((index) => planned[index].name),
  })

  return true
}

/**
 * 装粘贴拦截：document 捕获阶段，抢在 Lexical 的根元素监听之前跑。
 * @param ctx - 客户端上下文。
 * @param deps - 依赖包。
 * @returns 卸载函数。
 */
function installPasteInterceptor(ctx, deps) {
  const doc = deps.doc
  const onPaste = (event) => {
    let consumed = false
    try {
      consumed = handlePaste(ctx, deps, event)
    } catch (error) {
      deps.report('paste handler failed', error)
      consumed = false
    }
    if (consumed) {
      event.preventDefault()
      event.stopImmediatePropagation()
    }
  }
  doc.addEventListener('paste', onPaste, true)
  return () => doc.removeEventListener('paste', onPaste, true)
}

/* ---------------------------------------------------------------------------
 * 9. 悬浮预览
 * ------------------------------------------------------------------------- */

/**
 * 装悬浮探测：一个 pointermove（rAF 节流）驱动，命中就延时弹卡，离开就收。
 * @param deps - { doc, card, registry }。
 * @returns 卸载函数。
 */
function installHoverPreview(deps) {
  const { doc, card, registry } = deps
  const view = doc.defaultView
  const requestFrame =
    typeof view?.requestAnimationFrame === 'function' ? view.requestAnimationFrame.bind(view) : (fn) => setTimeout(fn, 16)
  let timer = null
  let pendingKey = null
  let openKey = null
  let frameQueued = false
  let point = { x: 0, y: 0 }

  const clearTimer = () => {
    if (timer !== null) {
      clearTimeout(timer)
      timer = null
    }
  }

  const hide = () => {
    clearTimer()
    pendingKey = null
    if (openKey !== null) {
      openKey = null
      card.hide()
    }
  }

  const evaluate = () => {
    /* 设置页可能把悬浮预览（或整个插件）关掉：关了就把已经弹出的卡一起收掉 */
    if (settings.hoverPreview !== true || settings.enabled !== true) {
      hide()
      return
    }
    const hit = hitTest(doc, registry, point.x, point.y)
    if (hit === null) {
      hide()
      return
    }
    if (openKey === hit.key) return
    if (pendingKey === hit.key) return
    clearTimer()
    if (openKey !== null) {
      openKey = null
      card.hide()
    }
    pendingKey = hit.key
    timer = setTimeout(() => {
      timer = null
      const fresh = hitTest(doc, registry, point.x, point.y)
      if (fresh === null || fresh.key !== hit.key) return
      openKey = fresh.key
      card.show(fresh.record, fresh.rect)
    }, Math.max(0, settings.hoverDelayMs))
  }

  const onPointerMove = (event) => {
    point = { x: event.clientX, y: event.clientY }
    if (frameQueued) return
    frameQueued = true
    requestFrame(() => {
      frameQueued = false
      evaluate()
    })
  }
  const onPointerDown = () => hide()
  const onScroll = () => hide()
  const onResize = () => hide()
  const onKeyDown = (event) => {
    if (event.key === 'Escape') hide()
  }

  doc.addEventListener('pointermove', onPointerMove, { passive: true })
  doc.addEventListener('pointerdown', onPointerDown, true)
  doc.addEventListener('scroll', onScroll, true)
  doc.addEventListener('keydown', onKeyDown, true)
  if (view !== null && view !== undefined && typeof view.addEventListener === 'function') {
    view.addEventListener('resize', onResize, { passive: true })
    view.addEventListener('blur', onScroll)
  }

  return () => {
    clearTimer()
    doc.removeEventListener('pointermove', onPointerMove, { passive: true })
    doc.removeEventListener('pointerdown', onPointerDown, true)
    doc.removeEventListener('scroll', onScroll, true)
    doc.removeEventListener('keydown', onKeyDown, true)
    if (view !== null && view !== undefined && typeof view.removeEventListener === 'function') {
      view.removeEventListener('resize', onResize, { passive: true })
      view.removeEventListener('blur', onScroll)
    }
    hide()
  }
}

/* ---------------------------------------------------------------------------
 * 9.5 缩略图角标（dock 的附件轨 + 已发送气泡里的图片行）
 * ------------------------------------------------------------------------- */

/** 角标元素的标记属性（既用来查找，也用来判重）。 */
const BADGE_ATTRIBUTE = 'data-dsh-inline-paste-badge'

/**
 * 从缩略图的 alt 里解析出序号。
 *
 * 官方两处的 alt 填的都是文件名：dock 是 `attachment.file.name`，气泡里是持久附件
 * ref 的 `name`（也就是发给模型时那行 `Image "image-1.png" …` 的来源）。
 * 所以序号是**读出来的**，不是数出来的 —— 用户删过图也不会错位。
 * @param alt - 缩略图 alt。
 * @returns {index, name} 或 undefined。
 */
function badgeNumberFromAlt(alt) {
  if (typeof alt !== 'string') return undefined
  const name = alt.trim()
  const match = NAME_PATTERN.exec(name)
  if (match === null) return undefined
  const index = Number(match[1])
  if (!Number.isSafeInteger(index) || index < 1) return undefined
  return { index, name }
}

/** 清掉本插件挂过的所有角标。 */
function clearThumbnailBadges(doc) {
  for (const badge of doc.querySelectorAll(`[${BADGE_ATTRIBUTE}]`)) badge.remove()
}

/**
 * 扫一遍并补齐角标（幂等）。
 *
 * 只认 `[data-composer-card]`（输入框上方的附件轨）和 `[data-message-attachments]`
 * （已发送气泡的图片行）里、alt 长得像本插件命名规则的缩略图。
 * @param doc - document。
 */
function syncThumbnailBadges(doc) {
  const size = BADGE_SIZES.includes(settings.badgeSize) ? settings.badgeSize : 'md'
  if (size === 'off' || settings.enabled !== true) {
    clearThumbnailBadges(doc)
    return
  }
  let images
  try {
    images = doc.querySelectorAll('[data-composer-card] img[alt], [data-message-attachments] img[alt]')
  } catch (error) {
    return
  }
  const live = new Set()
  for (const image of images) {
    const parsed = badgeNumberFromAlt(image.getAttribute('alt'))
    if (parsed === undefined) continue
    const host = image.parentElement
    if (host === null || host === undefined) continue
    live.add(host)
    /* button 默认 static，角标要绝对定位就得给它一个定位上下文；内联样式改动极小 */
    try {
      if (typeof getComputedStyle === 'function' && getComputedStyle(host).position === 'static') host.style.position = 'relative'
    } catch (error) {
      /* 拿不到计算样式就赌它是定位过的 */
    }
    let badge = host.querySelector(`[${BADGE_ATTRIBUTE}]`)
    if (badge === null) {
      badge = doc.createElement('span')
      badge.setAttribute(BADGE_ATTRIBUTE, '')
      host.appendChild(badge)
    }
    /* 类名每次都写一遍：设置页改档位后，下一次扫描就把尺寸换过来（同一个节点，不重挂） */
    const className = `dsh-ip-badge dsh-ip-badge--${size}`
    if (badge.className !== className) badge.className = className
    const text = String(parsed.index)
    if (badge.textContent !== text) badge.textContent = text
    if (badge.getAttribute('title') !== parsed.name) badge.setAttribute('title', parsed.name)
    /* 缩略图本身也挂全名，悬浮就能看到 pic-1.png，不用点开 */
    if (image.getAttribute('title') !== parsed.name) image.setAttribute('title', parsed.name)
  }
  /* 过期的角标（alt 变了 / 图片被换成非本插件命名的）顺手清掉 */
  for (const badge of doc.querySelectorAll(`[${BADGE_ATTRIBUTE}]`)) {
    const host = badge.parentElement
    if (host === null || host === undefined || !live.has(host)) badge.remove()
  }
}

/**
 * 装角标：先扫一遍，然后跟着 DOM 变化重扫（节流）。
 *
 * 为什么需要 MutationObserver：角标是挂进 React 管的 DOM 里的（官方的附件轨是
 * single slot，抢过来就得重写整条轨，不值得），React 重渲染时有概率把它冲掉 ——
 * 冲掉后再挂一次即可，功能完全不受影响。
 * @param deps - 依赖包。
 * @returns 卸载函数。
 */
function installThumbnailBadges(deps) {
  const doc = deps.doc
  let timer = null
  let lastScan = 0
  let observer = null

  const scan = () => {
    timer = null
    lastScan = Date.now()
    try {
      syncThumbnailBadges(doc)
    } catch (error) {
      deps.report('badge sync failed', error)
    }
  }

  const schedule = () => {
    if (timer !== null) return
    const wait = Math.max(0, (Number.isFinite(settings.badgeScanMinIntervalMs) ? settings.badgeScanMinIntervalMs : 80) - (Date.now() - lastScan))
    timer = setTimeout(scan, wait)
    if (typeof timer?.unref === 'function') timer.unref()
  }

  scan()
  if (typeof MutationObserver === 'function' && doc.body !== null && doc.body !== undefined) {
    try {
      observer = new MutationObserver(schedule)
      observer.observe(doc.body, { childList: true, subtree: true })
    } catch (error) {
      deps.report('badge observer failed', error)
    }
  }

  return () => {
    if (timer !== null) {
      clearTimeout(timer)
      timer = null
    }
    try {
      observer?.disconnect()
    } catch (error) {
      /* 忽略 */
    }
    clearThumbnailBadges(doc)
  }
}

